                if job["qpu"] == qpu_index:
                    qubo[f"x{data['resources'].index(job)}", f"x{data['resources'].index(job)}"] = 1
                    if data["resources"].index(job) < qpu_limit:
                        continue
                    qubo[f"x{data['resources'].index(job)}", f"x{data['resources'].index(job)}"] += 10000

        elif constraint["type"] == "shared_decoder_conflict":
            qubo[f"x{data['resources'].index(constraint['expression'][0])}", f"x{data['resources'].index(constraint['expression'][1])}"] = 1
